class Solution {
public:
    int shortestWordDistance(vector<string>& wordsDict, string word1, string word2) {
        int idx1 = -1, idx2 = -1;
        int minDist = wordsDict.size();
        bool same = (word1 == word2);
        for (int i = 0; i < (int)wordsDict.size(); ++i) {
            if (wordsDict[i] == word1) {
                if (same) {
                    if (idx1 != -1) minDist = min(minDist, i - idx1);
                    idx1 = i;
                } else {
                    idx1 = i;
                    if (idx2 != -1) minDist = min(minDist, abs(idx1 - idx2));
                }
            } else if (!same && wordsDict[i] == word2) {
                idx2 = i;
                if (idx1 != -1) minDist = min(minDist, abs(idx1 - idx2));
            }
        }
        return minDist;
    }
};

class Solution {
    public int shortestWordDistance(String[] wordsDict, String word1, String word2) {
        int idx1 = -1, idx2 = -1;
        int minDist = wordsDict.length;
        boolean same = word1.equals(word2);
        for (int i = 0; i < wordsDict.length; i++) {
            if (wordsDict[i].equals(word1)) {
                if (same) {
                    if (idx1 != -1) minDist = Math.min(minDist, i - idx1);
                    idx1 = i;
                } else {
                    idx1 = i;
                    if (idx2 != -1) minDist = Math.min(minDist, Math.abs(idx1 - idx2));
                }
            } else if (!same && wordsDict[i].equals(word2)) {
                idx2 = i;
                if (idx1 != -1) minDist = Math.min(minDist, Math.abs(idx1 - idx2));
            }
        }
        return minDist;
    }
}

