var shortestWordDistance = function(wordsDict, word1, word2) {
    let idx1 = -1, idx2 = -1;
    let minDist = wordsDict.length;
    const same = (word1 === word2);
    for (let i = 0; i < wordsDict.length; i++) {
        if (wordsDict[i] === word1) {
            if (same) {
                if (idx1 !== -1) minDist = Math.min(minDist, i - idx1);
                idx1 = i;
            } else {
                idx1 = i;
                if (idx2 !== -1) minDist = Math.min(minDist, Math.abs(idx1 - idx2));
            }
        } else if (!same && wordsDict[i] === word2) {
            idx2 = i;
            if (idx1 !== -1) minDist = Math.min(minDist, Math.abs(idx1 - idx2));
        }
    }
    return minDist;
};
